using HRIS.Api.Common; using HRIS.Api.Data; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Models.Enums;
namespace HRIS.Api.Services; public class LetterApprovalHandler:IApprovalHandler { private readonly AppDbContext _db; public LetterApprovalHandler(AppDbContext db)=>_db=db; public string RequestType=>ApprovalRequestTypes.Letter; public async Task OnCompletedAsync(ApprovalRequest request,ApprovalRequestStatus finalStatus){var x=await _db.LetterRequests.FindAsync(request.RequestRefId)??throw new NotFoundException("Permintaan surat tidak ditemukan.");x.Status=finalStatus switch{ApprovalRequestStatus.Approved=>"Approved",ApprovalRequestStatus.Rejected=>"Rejected",ApprovalRequestStatus.Cancelled=>"Cancelled",_=>x.Status};await _db.SaveChangesAsync();} }
